  "set.qz_cert_info_pre":       { ar: "أنشئ زوج مفاتيح QZ Tray (Certificate + Private Key) من موقع", bad: "Cotek mifteyan a QZ Tray (Certificate + Private Key) li malpera", tr: "QZ Tray anahtar çifti (Certificate + Private Key) oluşturmak için", en: "Create a QZ Tray key pair (Certificate + Private Key) from", de: "Erstelle ein QZ Tray Schlüsselpaar (Certificate + Private Key) auf" },
  "set.qz_cert_info_post":      { ar: "ثم الصق كلاً منهما هنا. الشهادة العامة تُثبَّت أيضاً في مجلد QZ Tray على كل جهاز.", bad: "çêbike paşê her duyan li vir bixin. Sertîfîkaya giştî di peldanka QZ Tray de li her cihazekê jî tê saz kirin.", tr: "bölümünden oluşturun, ardından her ikisini buraya yapıştırın. Ortak sertifika QZ Tray klasörüne de kurulur.", en: "then paste both here. The public certificate is also installed in the QZ Tray folder on each device.", de: "dann beide hier einfügen. Das öffentliche Zertifikat wird auch im QZ Tray Ordner auf jedem Gerät installiert." },
  "set.qz_public_cert":         { ar: "الشهادة العامة (Certificate)",  bad: "Sertîfîkaya giştî (Certificate)",  tr: "Genel Sertifika (Certificate)",  en: "Public Certificate",  de: "Öffentliches Zertifikat (Certificate)" },
